  bobj$var.estim <- "none"
  bobj$boot.controls <- list()
  if (is.list(obj$tx.wgt.man)) {
    bobj$tx.wgt.man <- lapply(obj$tx.wgt.man, "[", boot_sample)
  }
  bobj
